"""Warehouse fulfilment: packing slips for orders that are ready to pick and pack."""

from __future__ import annotations

from dataclasses import dataclass

from orders.application.errors import Conflict, OrderNotFound, ProductNotFound
from orders.application.order_service import OrderService
from orders.infrastructure.catalog import InMemoryProductCatalog
from orders.infrastructure.customers import InMemoryCustomerRepository
from orders.infrastructure.stock import InMemoryStockRepository


@dataclass(frozen=True)
class PackingSlipLine:
    sku: str
    name: str
    quantity: int


@dataclass(frozen=True)
class PackingSlip:
    order_id: str
    customer_name: str | None
    lines: tuple[PackingSlipLine, ...]


@dataclass(frozen=True)
class LowStockProduct:
    sku: str
    name: str
    on_hand: int


class FulfilmentService:
    def __init__(self, orders: OrderService, customers: InMemoryCustomerRepository,
                 catalog: InMemoryProductCatalog, stock: InMemoryStockRepository) -> None:
        self._orders = orders
        self._customers = customers
        self._catalog = catalog
        self._stock = stock

    def low_stock(self, threshold: int) -> list[LowStockProduct]:
        """Active products with fewer than ``threshold`` units on hand, lowest stock first."""
        products = [
            LowStockProduct(p.sku, p.name, self._stock.get(p.sku))
            for p in self._catalog.list_all()
            if p.active and self._stock.get(p.sku) < threshold
        ]
        return sorted(products, key=lambda p: (p.on_hand, p.sku))

    def fulfilment_summary(self) -> FulfilmentSummary:
        """Dashboard figures: open orders, units to pick across them, and low-stock products."""
        open_orders = [o for o in self._orders.list_all() if o.status != "cancelled"]
        return FulfilmentSummary(
            open_orders=len(open_orders),
            units_to_pick=sum(item.quantity for o in open_orders for item in o.items),
            low_stock_products=len(self.low_stock(LOW_STOCK_LINE)),
        )

    def restock(self, sku: str, quantity: int) -> int:
        """Add ``quantity`` units to a product's stock and return the new level.

        Raises ``ProductNotFound`` if the SKU is not in the catalogue. The stock repository is
        shared with order placement, so the added units are orderable straight away.
        """
        if self._catalog.get(sku) is None:
            raise ProductNotFound(sku)
        new_level = self._stock.get(sku) + quantity
        self._stock.set(sku, new_level)
        return new_level

    def packing_slip(self, order_id: str) -> PackingSlip:
        """Packing slip for an order, with lines in the order's item order.

        Raises ``OrderNotFound`` for unknown orders and ``Conflict`` for cancelled ones.
        """
        order = self._orders.get_order(order_id)
        if order.status == "cancelled":
            raise Conflict(f"order {order_id} is cancelled")
        customer = self._customers.get(order.customer_id)
        lines = tuple(
            PackingSlipLine(item.sku, self._catalog.get(item.sku).name, item.quantity)
            for item in order.items
        )
        return PackingSlip(order.order_id, customer.name if customer is not None else None, lines)

